    13→
    14→  <style>
    15→    /* ===== DARK THEME (default) ===== */
    16→    :root {
    17→      --bg:          #0A0F1E;
    18→      --bg-alt:      #080C18;
    19→      --bg-card:     #0D1526;
    20→      --bg-card2:    #111827;
    21→      --bg-nav:      rgba(10,15,30,0.88);
    22→      --blue:        #2979FF;
    23→      --cyan:        #00E5FF;
    24→      --teal:        #00BFA5;
    25→      --gold:        #FFD600;
    26→      --text:        #E8EDF5;
    27→      --text-muted:  #8899BB;
    28→      --border:      rgba(41,121,255,0.22);
    29→      --border-hov:  rgba(0,229,255,0.45);
    30→      --glass:       rgba(13,21,38,0.80);
    31→      --shadow:      0 6px 32px rgba(0,0,0,0.40);
    32→      --wave-a:      #080C18;
    33→      --wave-b:      #0A0F1E;
    34→      --toggle-icon: "☀";
    35→    }
    36→
    37→    /* ===== LIGHT THEME ===== */
    38→    [data-theme="light"] {
    39→      --bg:          #F0F5FF;
    40→      --bg-alt:      #E5EDFF;
    41→      --bg-card:     #FFFFFF;
    42→      --bg-card2:    #F4F8FF;
    43→      --bg-nav:      rgba(240,245,255,0.92);
    44→      --blue:        #1565C0;
    45→      --cyan:        #0077B6;
    46→      --teal:        #00796B;
    47→      --gold:        #E65100;
    48→      --text:        #0D1117;
    49→      --text-muted:  #4B5568;
    50→      --border:      rgba(21,101,192,0.20);
    51→      --border-hov:  rgba(0,119,182,0.45);
    52→      --glass:       rgba(255,255,255,0.85);
    53→      --shadow:      0 6px 32px rgba(0,0,0,0.10);
    54→      --wave-a:      #E5EDFF;
    55→      --wave-b:      #F0F5FF;
    56→    }
    57→
    58→    /* ===== RESET ===== */
    59→    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    60→    html { scroll-behavior: smooth; }
    61→    body {
    62→      font-family: 'Inter', sans-serif;
    63→      font-size: 17px;
    64→      background: var(--bg);
    65→      color: var(--text);
    66→      line-height: 1.75;
    67→      overflow-x: hidden;
    68→      transition: background 0.35s ease, color 0.35s ease;
    69→    }
    70→    h1,h2,h3,h4,h5 { font-family: 'Space Grotesk', sans-serif; line-height: 1.2; }
    71→    a { color: inherit; text-decoration: none; }
    72→    img { max-width: 100%; display: block; }
    73→
    74→    /* ===== LAYOUT ===== */
    75→    .container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.75rem; }
    76→    .section    { padding: 3.5rem 0; }
    77→
    78→    /* ===== TYPOGRAPHY HELPERS ===== */
    79→    .section-label {
    80→      font-family: 'JetBrains Mono', monospace;
    81→      font-size: 0.78rem;
    82→      letter-spacing: 0.2em;
    83→      text-transform: uppercase;
    84→      color: var(--cyan);
    85→      margin-bottom: 0.6rem;
    86→    }
    87→    .section-title {
    88→      font-size: clamp(2rem, 3.2vw, 2.75rem);
    89→      font-weight: 700;
    90→      margin-bottom: 1rem;
    91→    }
    92→    .section-subtitle {
    93→      color: var(--text-muted);
    94→      font-size: 1.12rem;
    95→      max-width: 640px;
    96→      line-height: 1.75;
    97→    }
    98→    .section-header { text-align: center; margin-bottom: 2.25rem; }
    99→    .section-header .section-subtitle { margin: 0 auto; }
   100→
   101→    /* ===== GLASS CARD ===== */
   102→    .glass-card {
   103→      background: var(--glass);
   104→      backdrop-filter: blur(12px);
   105→      -webkit-backdrop-filter: blur(12px);
   106→      border: 1px solid var(--border);
   107→      border-radius: 14px;
   108→      transition: border-color 0.3s, box-shadow 0.3s;
   109→    }
   110→
   111→    /* ===== BADGE ===== */
   112→    .badge {
   113→      display: inline-flex; align-items: center; gap: 0.4rem;
   114→      padding: 0.28rem 0.8rem; border-radius: 999px;
   115→      font-size: 0.76rem; font-weight: 600; letter-spacing: 0.04em;
   116→    }
   117→    .badge-blue  { background: rgba(41,121,255,0.13); color: var(--blue);  border: 1px solid rgba(41,121,255,0.28); }
   118→    .badge-cyan  { background: rgba(0,229,255,0.11);  color: var(--cyan);  border: 1px solid rgba(0,229,255,0.25); }
   119→    .badge-gold  { background: rgba(255,214,0,0.11);  color: var(--gold);  border: 1px solid rgba(255,214,0,0.25); }
   120→    .badge-teal  { background: rgba(0,191,165,0.11);  color: var(--teal);  border: 1px solid rgba(0,191,165,0.25); }
   121→    .badge-gray  { background: rgba(136,153,187,0.11);color: var(--text-muted); border: 1px solid rgba(136,153,187,0.2); }
   122→
   123→    /* ===== BUTTONS ===== */
   124→    .btn {
   125→      display: inline-flex; align-items: center; gap: 0.55rem;
   126→      padding: 0.85rem 2rem; border-radius: 999px;
   127→      font-weight: 600; font-size: 1rem; cursor: pointer;
   128→      border: none; transition: all 0.3s; font-family: 'Inter', sans-serif;
   129→    }
   130→    .btn-primary {
   131→      background: var(--blue); color: #fff;
   132→      box-shadow: 0 0 28px rgba(41,121,255,0.45);
   133→    }
   134→    .btn-primary:hover {
   135→      filter: brightness(1.12);
   136→      box-shadow: 0 0 40px rgba(41,121,255,0.65);
   137→      transform: translateY(-2px);
   138→    }
   139→    .btn-outline {
   140→      background: transparent; color: var(--cyan);
   141→      border: 1.5px solid var(--cyan);
   142→    }
   143→    .btn-outline:hover {
   144→      background: rgba(0,229,255,0.08);
   145→      box-shadow: 0 0 24px rgba(0,229,255,0.35);
   146→      transform: translateY(-2px);
   147→    }
   148→    .btn-sm { padding: 0.55rem 1.35rem; font-size: 0.9rem; }
   149→
   150→    /* ===== FADE-IN ===== */
   151→    .fade-in { opacity: 0; transform: translateY(28px); transition: opacity 0.7s ease, transform 0.7s ease; }
   152→    .fade-in.visible { opacity: 1; transform: translateY(0); }
   153→    .fade-in.d1 { transition-delay: 0.1s; }
   154→    .fade-in.d2 { transition-delay: 0.2s; }
   155→    .fade-in.d3 { transition-delay: 0.3s; }
   156→    .fade-in.d4 { transition-delay: 0.4s; }
   157→
   158→    /* ===== WAVES ===== */
   159→    .wave-wrap { display: block; line-height: 0; overflow: hidden; }
   160→    .wave-wrap svg { display: block; }
   161→
   162→    /* ============================================================
   163→       NAVBAR
   164→    ============================================================ */
   165→    #navbar {
   166→      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
   167→      padding: 1.2rem 0;
   168→      transition: background 0.4s, padding 0.4s, backdrop-filter 0.4s, border-color 0.4s;
   169→      border-bottom: 1px solid transparent;
   170→    }
   171→    #navbar.scrolled {
   172→      background: var(--bg-nav);
   173→      backdrop-filter: blur(18px);
   174→      -webkit-backdrop-filter: blur(18px);
   175→      border-bottom-color: var(--border);
   176→      padding: 0.7rem 0;
   177→    }
   178→    .nav-inner { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
   179→
   180→    .nav-logo {
   181→      font-family: 'Space Grotesk', sans-serif;
   182→      font-size: 1.45rem; font-weight: 700; letter-spacing: 0.04em;
   183→      color: var(--cyan); text-shadow: 0 0 20px rgba(0,229,255,0.4);
   184→      white-space: nowrap;
   185→    }
   186→    .nav-logo span { color: var(--text); }
   187→
   188→    .nav-links {
   189→      display: none; align-items: center; gap: 0.15rem; list-style: none;
   190→    }
   191→    .nav-links a {
   192→      padding: 0.5rem 0.9rem; border-radius: 8px;
   193→      font-size: 0.95rem; font-weight: 500; color: var(--text-muted);
   194→      transition: color 0.25s, background 0.25s;
   195→    }
   196→    .nav-links a:hover { color: var(--text); background: rgba(255,255,255,0.06); }
   197→
   198→    .nav-right { display: none; align-items: center; gap: 0.75rem; }
   199→
   200→    /* Theme toggle */
   201→    .theme-btn {
   202→      width: 38px; height: 38px; border-radius: 10px;
   203→      background: rgba(255,255,255,0.06); border: 1px solid var(--border);
   204→      color: var(--text-muted); font-size: 1rem;
   205→      display: flex; align-items: center; justify-content: center;
   206→      cursor: pointer; transition: all 0.3s;
   207→    }
   208→    .theme-btn:hover { color: var(--cyan); border-color: var(--border-hov); }
   209→
   210→    /* Hamburger */
   211→    .hamburger {
   212→      display: flex; flex-direction: column; gap: 5px;
   213→      cursor: pointer; background: none; border: none; padding: 4px;
   214→    }
   215→    .hamburger span {
   216→      display: block; width: 24px; height: 2px;
   217→      background: var(--text); border-radius: 2px; transition: all 0.3s;
   218→    }
   219→    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
   220→    .hamburger.open span:nth-child(2) { opacity: 0; }
   221→    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }
   222→
   223→    /* Mobile menu */
   224→    .mobile-menu {
   225→      display: none; flex-direction: column;
   226→      background: var(--bg-nav); backdrop-filter: blur(18px);
   227→      border-top: 1px solid var(--border);
   228→      padding: 1rem 1.75rem 1.75rem;
   229→    }
   230→    .mobile-menu.open { display: flex; }
   231→    .mobile-menu a {
   232→      padding: 0.8rem 0; border-bottom: 1px solid rgba(255,255,255,0.05);
   233→      font-size: 1rem; font-weight: 500; color: var(--text-muted);
   234→      transition: color 0.25s;
   235→    }
   236→    .mobile-menu a:hover { color: var(--cyan); }
   237→    .mobile-menu .btn { margin-top: 1.1rem; align-self: flex-start; }
   238→
   239→    @media (min-width: 768px) {
   240→      .nav-links  { display: flex; }
   241→      .nav-right  { display: flex; }
   242→      .hamburger  { display: none; }
   243→    }
   244→
   245→    /* ============================================================
   246→       HERO
   247→    ============================================================ */
   248→    #hero {
   249→      position: relative; min-height: 100vh;
   250→      display: flex; align-items: center; justify-content: center; overflow: hidden;
   251→      background: var(--bg);
   252→    }
   253→    #hero-canvas { position: absolute; inset: 0; z-index: 0; }
   254→    .hero-overlay {
   255→      position: absolute; inset: 0; z-index: 1;
   256→      background: radial-gradient(ellipse 80% 60% at 50% 40%, rgba(41,121,255,0.09) 0%, transparent 68%);
   257→    }
   258→    [data-theme="light"] .hero-overlay {
   259→      background: radial-gradient(ellipse 80% 60% at 50% 40%, rgba(21,101,192,0.06) 0%, transparent 68%);
   260→    }
   261→
   262→    .hero-content {
   263→      position: relative; z-index: 2;
   264→      text-align: center; max-width: 940px;
   265→      padding: 0 1.75rem; padding-top: 5rem;
   266→    }
   267→
   268→    .hero-badge {
   269→      display: inline-flex; align-items: center; gap: 0.55rem;
   270→      padding: 0.45rem 1.2rem; border-radius: 999px;
   271→      background: rgba(41,121,255,0.1); border: 1px solid rgba(41,121,255,0.3);
   272→      font-family: 'JetBrains Mono', monospace;
   273→      font-size: 0.82rem; font-weight: 600; letter-spacing: 0.04em;
   274→      color: var(--blue); margin-bottom: 1.1rem;
   275→    }
   276→    .hero-badge i { color: var(--cyan); }
   277→
   278→    .hero-title {
   279→      font-size: clamp(2.2rem, 5vw, 3.75rem);
   280→      font-weight: 700; line-height: 1.15; margin-bottom: 0.9rem;
   281→      background: linear-gradient(135deg, var(--text) 0%, var(--cyan) 40%, var(--blue) 70%, var(--text) 100%);
   282→      background-size: 300% 300%;
   283→      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
   284→      background-clip: text;
   285→      animation: gradShift 7s ease infinite;
   286→    }
   287→    [data-theme="light"] .hero-title {
   288→      background: linear-gradient(135deg, #0D1117 0%, #0077B6 40%, #1565C0 70%, #0D1117 100%);
   289→      background-size: 300% 300%;
   290→      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
   291→      background-clip: text;
   292→    }
   293→    @keyframes gradShift {
   294→      0%   { background-position: 0% 50%; }
   295→      50%  { background-position: 100% 50%; }
   296→      100% { background-position: 0% 50%; }
   297→    }
   298→
   299→    .hero-tagline {
   300→      font-size: clamp(1.05rem, 2vw, 1.25rem);
   301→      color: var(--text-muted); margin-bottom: 1.75rem; font-weight: 400;
   302→    }
   303→    .hero-tagline strong { color: var(--cyan); font-weight: 600; }
   304→
   305→    .hero-actions {
   306→      display: flex; flex-wrap: wrap; gap: 1rem;
   307→      justify-content: center; margin-bottom: 2rem;
   308→    }
   309→
   310→    /* Countdown */
   311→    .countdown-wrapper { margin-top: 0.25rem; }
   312→    .countdown-label {
   313→      font-family: 'JetBrains Mono', monospace; font-size: 0.72rem;
   314→      letter-spacing: 0.15em; color: var(--text-muted);
   315→      text-transform: uppercase; margin-bottom: 0.85rem;
   316→    }
   317→    .countdown {
   318→      display: flex; justify-content: center; gap: 1.1rem; flex-wrap: wrap;
   319→    }
   320→    .cd-unit { display: flex; flex-direction: column; align-items: center; gap: 0.3rem; }
   321→    .cd-val {
   322→      font-family: 'JetBrains Mono', monospace;
   323→      font-size: clamp(2rem, 4.5vw, 2.8rem); font-weight: 500;
   324→      color: var(--cyan); text-shadow: 0 0 20px rgba(0,229,255,0.45);
   325→      min-width: 3ch; text-align: center; line-height: 1;
   326→    }
   327→    .cd-lbl { font-size: 0.68rem; text-transform: uppercase; letter-spacing: 0.1em; color: var(--text-muted); }
   328→    .cd-sep {
   329→      font-family: 'JetBrains Mono', monospace; font-size: 2.2rem;
   330→      color: var(--border); align-self: center; padding-bottom: 1.1rem;
   331→    }
   332→
   333→    .hero-scroll {
   334→      position: absolute; bottom: 2.5rem; left: 50%;
   335→      transform: translateX(-50%); z-index: 2;
   336→      display: flex; flex-direction: column; align-items: center; gap: 0.4rem;
   337→      color: var(--text-muted); font-size: 0.75rem; letter-spacing: 0.1em;
   338→      animation: scrollBounce 2.2s infinite;
   339→    }
   340→    @keyframes scrollBounce {
   341→      0%,100% { transform: translateX(-50%) translateY(0); }
   342→      50%      { transform: translateX(-50%) translateY(8px); }
   343→    }
   344→
   345→    /* ============================================================
   346→       ICIP INFO BANNER
   347→    ============================================================ */
   348→    .icip-banner {
   349→      padding: 1.75rem 2rem;
   350→      border-radius: 16px;
   351→      margin-top: 2.5rem;
   352→      border-left: 4px solid var(--blue);
   353→    }
   354→    .icip-banner .icip-flag {
   355→      font-size: 0.78rem; font-family: 'JetBrains Mono', monospace;
   356→      letter-spacing: 0.15em; text-transform: uppercase;
   357→      color: var(--blue); margin-bottom: 0.5rem;
   358→      display: flex; align-items: center; gap: 0.5rem;
   359→    }
   360→    .icip-banner h3 {
   361→      font-size: 1.2rem; font-weight: 700; margin-bottom: 0.85rem;
   362→    }
   363→    .icip-banner p {
   364→      color: var(--text-muted); font-size: 1.05rem; line-height: 1.8;
   365→    }
   366→    .icip-meta {
   367→      display: flex; flex-wrap: wrap; gap: 0.75rem; margin-top: 1.25rem;
   368→    }
   369→
   370→    /* ============================================================
   371→       ABOUT
   372→    ============================================================ */
   373→    #about { background: var(--bg); }
   374→
   375→    .about-grid {
   376→      display: grid; grid-template-columns: 1fr; gap: 2rem;
   377→    }
   378→    @media (min-width: 1024px) {
   379→      .about-grid { grid-template-columns: 1.25fr 1fr; align-items: start; }
   380→    }
   381→
   382→    .about-text p {
   383→      color: var(--text-muted); font-size: 1.1rem;
   384→      line-height: 1.85; margin-bottom: 1.35rem;
   385→    }
   386→    .about-text p:last-child { margin-bottom: 0; }
   387→
   388→    .stat-cards {
   389→      display: grid; grid-template-columns: repeat(3,1fr); gap: 1rem; margin-top: 1.5rem;
   390→    }
   391→    .stat-card {
   392→      padding: 1.35rem 1rem; text-align: center;
   393→      border-radius: 12px; background: var(--bg-card2); border: 1px solid var(--border);
   394→    }
   395→    .stat-card i { font-size: 1.5rem; color: var(--cyan); margin-bottom: 0.55rem; display: block; }
   396→    .stat-val { font-family: 'Space Grotesk', sans-serif; font-weight: 700; font-size: 1.1rem; }
   397→    .stat-lbl { font-size: 0.75rem; color: var(--text-muted); margin-top: 0.15rem; }
   398→
   399→    /* Topic tags */
   400→    .tags-block h4 {

