   400→    .tags-block h4 {
   401→      font-family: 'JetBrains Mono', monospace; font-size: 0.78rem;
   402→      text-transform: uppercase; letter-spacing: 0.12em;
   403→      color: var(--text-muted); margin-bottom: 1.2rem;
