   412→      background: rgba(0,229,255,0.1); border-color: rgba(0,229,255,0.4);
   413→      color: var(--cyan); box-shadow: 0 0 14px rgba(0,229,255,0.18);
   414→    }
   415→
   416→    /* ============================================================
   417→       SPEAKERS
   418→    ============================================================ */
   419→    #speakers { background: var(--bg-alt); }
   420→
   421→    .speakers-tba {
   422→      max-width: 680px; margin: 0 auto;
   423→      text-align: center; padding: 2.25rem 2rem;
   424→      border-radius: 20px;
   425→    }
   426→    .speakers-tba-icon {
   427→      width: 80px; height: 80px; border-radius: 50%;
   428→      background: rgba(41,121,255,0.1); border: 2px solid rgba(41,121,255,0.25);
   429→      display: flex; align-items: center; justify-content: center;
   430→      margin: 0 auto 1.25rem; font-size: 2rem; color: var(--blue);
   431→    }
   432→    .speakers-tba h3 { font-size: 1.55rem; margin-bottom: 1rem; }
   433→    .speakers-tba p { color: var(--text-muted); font-size: 1.08rem; line-height: 1.8; margin-bottom: 0.75rem; }
   434→    .speakers-tba .badges { display: flex; gap: 0.65rem; justify-content: center; flex-wrap: wrap; margin-top: 1.5rem; }
   435→
   436→    /* ============================================================
   437→       SCHEDULE
   438→    ============================================================ */
   439→    #schedule { background: var(--bg); }
   440→
   441→    .schedule-note {
   442→      text-align: center; margin-bottom: 2rem;
   443→      color: var(--text-muted); font-size: 1.05rem;
   444→    }
   445→
   446→    .timeline { position: relative; max-width: 820px; margin: 0 auto; }
   447→    .timeline::before {
   448→      content: ''; position: absolute; left: 1.5rem; top: 0; bottom: 0;
   449→      width: 2px;
