  1492→  // 2. CANVAS PARTICLES
  1493→  // ============================================================
  1494→  function initParticles() {
  1495→    const canvas = document.getElementById('hero-canvas');
  1496→    const ctx    = canvas.getContext('2d');
  1497→    const NUM    = 80;
  1498→    const DIST   = 150;
  1499→    let W, H, particles = [];
  1500→
  1501→    function isDark() {
  1502→      return document.documentElement.getAttribute('data-theme') !== 'light';
  1503→    }
  1504→
  1505→    function resize() {
  1506→      W = canvas.width  = window.innerWidth;
  1507→      H = canvas.height = window.innerHeight;
  1508→    }
  1509→
  1510→    class Particle {
  1511→      constructor() { this.reset(); }
  1512→      reset() {
  1513→        this.x  = Math.random() * W;
  1514→        this.y  = Math.random() * H;
  1515→        this.vx = (Math.random() - 0.5) * 0.4;
  1516→        this.vy = (Math.random() - 0.5) * 0.4;
  1517→        this.r  = Math.random() * 2 + 1;
  1518→        this.a  = Math.random() * 0.5 + 0.2;
  1519→      }
  1520→      update() {
  1521→        this.x += this.vx;
  1522→        this.y += this.vy;
  1523→        if (this.x < 0 || this.x > W) this.vx *= -1;
  1524→        if (this.y < 0 || this.y > H) this.vy *= -1;
  1525→      }
  1526→      draw() {
  1527→        const dark = isDark();
  1528→        ctx.beginPath();
  1529→        ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
  1530→        ctx.fillStyle = dark
  1531→          ? `rgba(41,121,255,${this.a})`
  1532→          : `rgba(21,101,192,${this.a * 0.7})`;
  1533→        ctx.fill();
  1534→      }
  1535→    }
  1536→
  1537→    function init() {
  1538→      resize();
  1539→      particles = [];
  1540→      for (let i = 0; i < NUM; i++) particles.push(new Particle());
  1541→    }
  1542→
  1543→    function animate() {
  1544→      ctx.clearRect(0, 0, W, H);
  1545→      const dark = isDark();
  1546→
  1547→      for (let i = 0; i < particles.length; i++) {
  1548→        for (let j = i + 1; j < particles.length; j++) {
  1549→          const dx   = particles[i].x - particles[j].x;
  1550→          const dy   = particles[i].y - particles[j].y;
  1551→          const dist = Math.sqrt(dx*dx + dy*dy);
  1552→          if (dist < DIST) {
  1553→            const op = (1 - dist / DIST) * (dark ? 0.22 : 0.15);
  1554→            const g  = ctx.createLinearGradient(particles[i].x, particles[i].y, particles[j].x, particles[j].y);
  1555→            if (dark) {
  1556→              g.addColorStop(0, `rgba(41,121,255,${op})`);
  1557→              g.addColorStop(1, `rgba(0,229,255,${op})`);
  1558→            } else {
  1559→              g.addColorStop(0, `rgba(21,101,192,${op})`);
  1560→              g.addColorStop(1, `rgba(0,119,182,${op})`);
  1561→            }
  1562→            ctx.beginPath();
  1563→            ctx.moveTo(particles[i].x, particles[i].y);
  1564→            ctx.lineTo(particles[j].x, particles[j].y);
  1565→            ctx.strokeStyle = g;
  1566→            ctx.lineWidth = 1;
  1567→            ctx.stroke();
  1568→          }
  1569→        }
  1570→      }
  1571→      particles.forEach(p => { p.update(); p.draw(); });
  1572→      requestAnimationFrame(animate);
  1573→    }
  1574→
  1575→    window.addEventListener('resize', init, { passive: true });
  1576→    init();
  1577→    animate();
  1578→  }
