  1581→  // 3. SCROLL ANIMATIONS
  1582→  // ============================================================
  1583→  function initScrollAnim() {
  1584→    const obs = new IntersectionObserver(entries => {
  1585→      entries.forEach(e => {
  1586→        if (e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); }
  1587→      });
  1588→    }, { threshold: 0.1 });
  1589→    document.querySelectorAll('.fade-in').forEach(el => obs.observe(el));
  1590→  }
