  1602→  // ============================================================
  1603→  // 5. COUNTDOWN
  1604→  // ============================================================
  1605→  function initCountdown(target) {
  1606→    function pad(n) { return String(n).padStart(2, '0'); }
  1607→    function tick() {
  1608→      const diff = target - Date.now();
  1609→      if (diff <= 0) {
  1610→        ['cd-days','cd-hours','cd-mins','cd-secs','mcd-d','mcd-h','mcd-m'].forEach(id => {
  1611→          const el = document.getElementById(id);
  1612→          if (el) el.textContent = '00';
  1613→        });
  1614→        return;
  1615→      }
  1616→      const d = Math.floor(diff / 86400000);
  1617→      const h = Math.floor((diff % 86400000) / 3600000);
  1618→      const m = Math.floor((diff % 3600000) / 60000);
  1619→      const s = Math.floor((diff % 60000) / 1000);
  1620→      [['cd-days',d],['cd-hours',h],['cd-mins',m],['cd-secs',s],
  1621→       ['mcd-d',d],['mcd-h',h],['mcd-m',m]].forEach(([id,v]) => {
  1622→        const el = document.getElementById(id);
  1623→        if (el) el.textContent = pad(v);
  1624→      });
  1625→    }
  1626→    tick();
  1627→    setInterval(tick, 1000);
  1628→  }
  1629→
  1630→  // ============================================================
  1631→  // 6. MOBILE MENU
  1632→  // ============================================================
  1633→  function initMobileMenu() {
  1634→    const btn  = document.getElementById('hamburger');
  1635→    const menu = document.getElementById('mobileMenu');
  1636→    btn.addEventListener('click', () => {
  1637→      btn.classList.toggle('open');
  1638→      menu.classList.toggle('open');
  1639→    });
  1640→    menu.querySelectorAll('a').forEach(a => a.addEventListener('click', () => {
  1641→      btn.classList.remove('open');
  1642→      menu.classList.remove('open');
  1643→    }));
  1644→  }
